import { cookies, headers } from 'next/headers'
import { Suspense } from 'react'
import { getProjectTotals } from '@/lib/projects'

export default function DashboardPage() {
  return (
    <main>
      <h1>Workspace</h1>
      <Suspense fallback={<MemberFallback />}>
        <MemberDetails />
      </Suspense>
      <ProjectTotals />
    </main>
  )
}

function MemberFallback() {
  return (
    <>
      <p>Welcome, loading member</p>
      <p>Team: loading</p>
      <p>Region: loading</p>
    </>
  )
}

async function MemberDetails() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'

  return (
    <>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </>
  )
}

async function ProjectTotals() {
  const totals = await getProjectTotals()
  return <p>{totals.active} active projects</p>
}

